function normalizeAiBaseUrl(apiUrl) {
  let u = (apiUrl || "").trim();
  if (!u) return "";
  u = u.replace(/\/+$/, "");
  if (KNOWN_VERSION_SEG.test(u)) return u;
  return `${u}/v1`;
}
